"""Prometheus metrics instrumentation for conversation observability."""

from prometheus_client import Counter, Histogram

# Inbound message volume
INBOUND_MESSAGES_TOTAL = Counter(
    "snappe_inbound_messages_total",
    "Total number of inbound WhatsApp webhook messages received",
    ["business_id", "message_type"],
)

# Outbound replies generated by the engine
OUTBOUND_REPLIES_TOTAL = Counter(
    "snappe_outbound_replies_total",
    "Total number of replies produced by Snappe engine",
    ["business_id", "delivered"],
)

# Handover events
HANDOVER_EVENTS_TOTAL = Counter(
    "snappe_handover_events_total",
    "Total number of human handover events triggered",
    ["business_id", "reason"],
)

# Pipeline processing latency
PROCESSING_DURATION_SECONDS = Histogram(
    "snappe_message_processing_duration_seconds",
    "Time spent processing an inbound message through guardrails and brain",
    ["business_id"],
    buckets=(0.05, 0.1, 0.25, 0.5, 1.0, 2.5, 5.0, 10.0),
)


def record_inbound_message(business_id: str, message_type: str = "text") -> None:
    """Increment inbound message counter."""
    INBOUND_MESSAGES_TOTAL.labels(business_id=business_id, message_type=message_type).inc()


def record_outbound_reply(business_id: str, delivered: bool) -> None:
    """Increment outbound reply counter."""
    OUTBOUND_REPLIES_TOTAL.labels(
        business_id=business_id, delivered="true" if delivered else "false"
    ).inc()


def record_handover(business_id: str, reason: str | None = None) -> None:
    """Increment handover event counter."""
    HANDOVER_EVENTS_TOTAL.labels(business_id=business_id, reason=reason or "unspecified").inc()
